H.background();
const w = H.W, h = H.H;
const p = Math.round(P.p), q = Math.round(P.q);
// trinomial x^2 + b x + c with roots -p, -q  -> factors (x+p)(x+q)
const b = p + q, c = p * q;
H.text("Factoring:  x² + bx + c = (x + p)(x + q)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const bs = (b >= 0 ? "+ " + b : "- " + Math.abs(b));
const cs = (c >= 0 ? "+ " + c : "- " + Math.abs(c));
H.text("x² " + bs + "x " + cs + " = (x " + (p >= 0 ? "+ " + p : "- " + Math.abs(p)) + ")(x " + (q >= 0 ? "+ " + q : "- " + Math.abs(q)) + ")", 24, 52, { color: H.colors.sub, size: 14 });
// Goal box: find two numbers that MULTIPLY to c and ADD to b
H.text("Need two numbers that  × = " + c + "   and   + = " + b, 60, 96, { color: H.colors.good, size: 15, weight: 600 });
// animated search: step a candidate i from -range..range, show i and (b-i)
const range = 9;
const span = 2 * range + 1;
const i = Math.round((t * 1.5) % span) - range;
const j = b - i;
const prod = i * j;
const hit = (prod === c);
const lineY = h * 0.42;
const x0 = 70, x1 = w - 70;
H.line(x0, lineY, x1, lineY, { color: H.colors.axis, width: 2 });
for (let k = -range; k <= range; k++) {
  const px = H.map(k, -range, range, x0, x1);
  H.line(px, lineY - 6, px, lineY + 6, { color: H.colors.grid, width: 1 });
  if (k % 3 === 0) H.text(k + "", px, lineY + 22, { color: H.colors.sub, size: 10, align: "center" });
}
const ix = H.map(H.clamp(i, -range, range), -range, range, x0, x1);
H.circle(ix, lineY, 8 + Math.sin(t * 5) * 2, { fill: hit ? H.colors.good : H.colors.warn, stroke: H.colors.bg, width: 2 });
H.text("try p = " + i + ",  q = " + j + "   →   p·q = " + prod + (hit ? "  ✓ matches c!" : "  (need " + c + ")"), 60, h * 0.42 + 50, { color: hit ? H.colors.good : H.colors.warn, size: 14, weight: 600 });
// area rectangle model for the factored form (x+p)(x+q)
const rx = 70, ry = h * 0.62, ux = 120, uc = 26;
const pw = ux + Math.max(0, p) * uc, qh = ux * 0.55 + Math.max(0, q) * uc * 0.55;
H.rect(rx, ry, pw, qh, { stroke: H.colors.accent, width: 2, fill: "rgba(124,196,255,0.10)", radius: 4 });
H.line(rx + ux, ry, rx + ux, ry + qh, { color: H.colors.accent2, width: 1.5, dash: [4, 4] });
H.line(rx, ry + ux * 0.55, rx + pw, ry + ux * 0.55, { color: H.colors.accent2, width: 1.5, dash: [4, 4] });
H.text("x", rx + ux * 0.5, ry - 8, { color: H.colors.accent, size: 13, align: "center" });
H.text("+" + p, rx + ux + (pw - ux) * 0.5, ry - 8, { color: H.colors.accent, size: 13, align: "center" });
H.text("(x+p)(x+q) = area", rx, ry + qh + 22, { color: H.colors.sub, size: 12 });
H.legend([{ label: "candidate", color: H.colors.warn }, { label: "match", color: H.colors.good }], w - 150, 96);
